1	type Cell = [number, number]; // [x, y]
2	
3	const NEIGHBOR_OFFSETS: Cell[] = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [0, -1], [0, 1],
6	  [1, -1], [1, 0], [1, 1],
7	];
8	
9	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
10	
11	const cellOf = (key: string): Cell => key.split(",").map(Number) as Cell;
12	
13	export function nextGeneration(cells: Cell[]): Cell[] {
14	  const alive = new Set(cells.map(keyOf));
15	  const neighborCounts = new Map<string, number>();
16	
17	  for (const [x, y] of cells) {
18	    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
19	      const neighborKey = keyOf([x + dx, y + dy]);
20	      neighborCounts.set(neighborKey, (neighborCounts.get(neighborKey) ?? 0) + 1);
21	    }
22	  }
23	
24	  const isAliveNextGen = (key: string, count: number): boolean =>
25	    count === 3 || (count === 2 && alive.has(key));
26	
27	  return [...neighborCounts]
28	    .filter(([key, count]) => isAliveNextGen(key, count))
29	    .map(([key]) => cellOf(key));
30	}
31

1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	type Cell = [number, number];
5	const sorted = (cells: Cell[]): Cell[] =>
6	  [...cells].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
7	
8	describe("Game of Life - Next Generation", () => {
9	  // Simplest case: empty grid
10	  it("should return an empty array for an empty grid", () => {
11	    expect(nextGeneration([])).toEqual([]);
12	  });
13	
14	  // Single cell dies (underpopulation, 0 neighbors)
15	  it("should kill a single live cell — [(0,0)] → []", () => {
16	    expect(nextGeneration([[0, 0]])).toEqual([]);
17	  });
18	
19	  // Rule 1 – Underpopulation (live cell with < 2 neighbors dies)
20	  it("should kill two cells each with 1 neighbor — [(0,1),(1,1)] → []", () => {
21	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
22	  });
23	
24	  // Rule 4 – Reproduction (dead cell with exactly 3 neighbors becomes alive)
25	  it("should bring a dead cell with exactly 3 neighbors to life — (1,1) becomes alive", () => {
26	    expect(sorted(nextGeneration([[0, 0], [1, 0], [0, 1]]))).toEqual(
27	      sorted([[0, 0], [1, 0], [0, 1], [1, 1]])
28	    );
29	  });
30	
31	  // Rule 2 – Survival (live cell with 2 or 3 neighbors lives on)
32	  it("should keep a live cell with 3 neighbors alive — center (1,1) survives", () => {
33	    // (1,1) is alive with exactly 3 live neighbors above it → survives
34	    expect(nextGeneration([[0, 0], [1, 0], [2, 0], [1, 1]])).toContainEqual([
35	      1, 1,
36	    ]);
37	  });
38	
39	  // Rule 3 – Overpopulation (live cell with > 3 neighbors dies)
40	  it("should kill a live cell with 4 neighbors — center (1,1) dies", () => {
41	    // Center (1,1) is surrounded by >3 live neighbors → dies
42	    const gen0: Cell[] = [
43	      [0, 0], [1, 0], [2, 0], [1, 1], [0, 2], [1, 2], [2, 2],
44	    ];
45	    expect(nextGeneration(gen0)).not.toContainEqual([1, 1]);
46	  });
47	
48	  // Block (still life) — unchanged
49	  it("should keep a block still — [(0,0),(1,0),(0,1),(1,1)] unchanged", () => {
50	    const block: Cell[] = [[0, 0], [1, 0], [0, 1], [1, 1]];
51	    expect(sorted(nextGeneration(block))).toEqual(sorted(block));
52	  });
53	
54	  // Blinker (oscillator) — vertical to horizontal
55	  it("should oscillate a blinker — [(0,0),(0,1),(0,2)] → [(-1,1),(0,1),(1,1)]", () => {
56	    expect(sorted(nextGeneration([[0, 0], [0, 1], [0, 2]]))).toEqual(
57	      sorted([[-1, 1], [0, 1], [1, 1]])
58	    );
59	  });
60	
61	  // Negative coordinates
62	  it("should handle negative coordinates in the blinker's second generation", () => {
63	    // Horizontal blinker (with negative x) oscillates back to vertical
64	    expect(sorted(nextGeneration([[-1, 1], [0, 1], [1, 1]]))).toEqual(
65	      sorted([[0, 0], [0, 1], [0, 2]])
66	    );
67	  });
68	});
