const survivesOrIsBorn = (key: string, count: number): boolean =>
  count === 3 || (count === 2 && alive.has(key));

const survivors: Cell[] = [];
for (const [key, count] of neighborCounts) {
  if (survivesOrIsBorn(key, count)) survivors.push(cellOf(key));
}
return survivors;

